      choices: ["고가 장비를 갖춘 전문의 중심의 진료","지역 주민이 쉽게 접근할 수 있어야 한다","주민이 지불할 수 있는 비용이어야 한다","지역사회의 적극적인 참여가 있어야 한다","주민이 수용할 수 있는 방법이어야 한다"],
      answerIndex: 0,
      explainCorrect: "일차보건의료(PHC)는 접근성, 수용가능성, 주민 참여, 지불부담능력(4A)을 기본 원칙으로 하는 필수 보건의료이다. 고가 장비와 전문의 중심의 병원 진료는 일차보건의료가 지향하는 방향과 반대되는 개념이다.",
      explainWrong: ["","접근성(accessibility)은 지리적·경제적·사회적으로 쉽게 이용할 수 있어야 한다는 일차보건의료(PHC)의 원칙이다.","지불부담능력(affordability)은 지역사회가 감당할 수 있는 비용이어야 한다는 원칙이다.","주민 참여(active participation)는 지역사회가 사업의 계획과 운영에 참여해야 한다는 핵심 원칙이다.","수용가능성(acceptability)은 주민이 문화적으로 받아들일 수 있는 방법으로 제공되어야 한다는 원칙이다."],
