      explainWrong: ["","예방·치료·재활은 질병의 자연사(natural history)에 따른 예방 수준의 구분으로 오타와 헌장(Ottawa Charter)의 전략이 아니다.","접근성·수용가능성·지불부담능력은 일차보건의료(PHC)의 기본 원칙(4A)에 속하는 개념이다.","계획·실행·평가는 보건사업 기획 과정의 순환 단계이다.","신고·격리·소독은 감염병 방역 조치로 건강증진(health promotion) 전략과는 다른 영역이다."],
