      answerIndex: 0,
      explainCorrect: "항아리형(pot form)은 출생률이 사망률보다 낮아 유소년 인구가 적고 인구가 감소하는 유형이다. 저출산이 지속되는 선진국에서 나타나며, 우리나라의 인구구조도 이 유형으로 이행하였다.",
      explainWrong: ["","피라미드형(pyramid form)은 출생률과 사망률이 모두 높아 인구가 증가하는 다산다사형(개발도상국형)이다.","종형(bell form)은 출생률과 사망률이 모두 낮아 인구가 정지 상태에 가까운 정지형이다.","별형(star form)은 생산연령 인구가 도시로 유입되어 15~49세 인구 비율이 높은 도시형이다.","표주박형(호로형)은 생산연령 인구가 빠져나간 농촌형으로, 인구 유출이 특징이다."],
