      explainWrong: ["","30%는 유소년부양비(300/1,000)만 계산한 값으로 노년 인구가 빠져 있다.","20%는 노년부양비(200/1,000)만 계산한 값이다.","33.3%는 비생산인구 500명을 생산인구가 아닌 총인구 1,500명으로 나눈 잘못된 계산이다.","66.7%는 생산인구가 총인구에서 차지하는 비율로, 부양비의 정의와 다르다."],
