      answerIndex: 0,
      explainCorrect: "결핵 치료의 핵심은 여러 약제를 병합하여 정해진 기간(표준 6개월 이상) 동안 중단 없이 복용하는 것이다. 불규칙한 복약과 조기 중단은 치료 실패와 다제내성 결핵(MDR-TB)의 주된 원인이므로, 복약확인(DOT) 등으로 순응도를 관리한다.",
      explainWrong: ["","증상은 치료 초기에 먼저 호전되므로 증상 소실을 기준으로 중단하면 재발과 내성 발생의 위험이 크다.","단일 약제 치료는 내성균의 선택적 증식을 유발하므로 결핵은 반드시 병합요법(combination therapy)을 원칙으로 한다.","적절한 치료를 시작하면 전염력이 빠르게 감소하므로 전체 환자의 장기 시설 격리는 불필요하다.","BCG는 소아의 중증 결핵을 예방하는 백신일 뿐 치료 효과는 없다."],
