      answerIndex: 0,
      explainCorrect: "일본뇌염(Japanese encephalitis)은 작은빨간집모기(Culex tritaeniorhynchus)가 매개하는 바이러스성 감염병이다. 돼지가 증폭 숙주 역할을 하며, 모기의 활동이 왕성한 여름과 초가을에 유행하므로 모기 방제와 예방접종이 주된 관리 방법이다.",
      explainWrong: ["","중국얼룩날개모기(Anopheles sinensis)는 말라리아(malaria)를 매개하는 모기이다.","털진드기(chigger mite)는 쯔쯔가무시증(scrub typhus)을 매개한다.","벼룩(flea)은 페스트(plague), 발진열(murine typhus) 등을 매개하는 절지동물이다.","몸니(body louse)는 발진티푸스(epidemic typhus)를 매개한다."],
