      choices: ["규폐증(silicosis)","석면폐증(asbestosis)","면폐증(byssinosis)","탄광부진폐증(coal workers' pneumoconiosis)","농부폐(farmer's lung)"],
      answerIndex: 0,
      explainCorrect: "규폐증(silicosis)은 유리규산(석영) 분진을 장기간 흡입하여 폐에 섬유화(fibrosis)가 일어나는 진폐증(pneumoconiosis)으로, 채석, 터널 굴착, 주물, 도자기 작업 등에서 발생한다. 폐결핵(pulmonary tuberculosis)이 잘 합병되는 것도 중요한 특징이다.",
      explainWrong: ["","석면폐증(asbestosis)은 석면 섬유의 흡입으로 발생하며 폐암과 악성중피종(malignant mesothelioma)의 위험을 높인다.","면폐증(byssinosis)은 면 분진에 노출된 근로자에서 나타나는 폐질환으로 원인 분진이 다르다.","탄광부진폐증(coal workers' pneumoconiosis)은 석탄 분진에 의한 진폐증으로 유리규산(free silica)이 주원인인 규폐증(silicosis)과 구별된다.","농부폐(farmer's lung)는 곰팡이 핀 건초 등 유기분진에 의한 과민성 폐장염(hypersensitivity pneumonitis)으로 진폐증(pneumoconiosis)과 기전이 다르다."],
