      explainCorrect: "미나마타병은 공장 폐수의 메틸수은(methylmercury)이 어패류에 농축되고 이를 섭취한 주민들에게 발생한 중독으로, 감각장애와 운동실조 등 신경 증상이 특징이다. 먹이연쇄를 통한 생물농축(bioaccumulation)의 대표적인 사례이다.",
      explainWrong: ["","이타이이타이병의 원인은 납(Pb)이 아니라 카드뮴(Cd)으로, 신세뇨관 장애와 골연화증(osteomalacia)에 의한 뼈의 통증이 특징이다.","카드뮴(Cd)은 이타이이타이병의 원인이며, 미나마타병은 메틸수은(methylmercury) 중독이다.","비소(As)는 이타이이타이병과 무관하며, 이 병의 원인은 카드뮴(Cd)이다.","납중독은 납(Pb) 자체에 의한 중독으로 빈혈과 신경장애가 특징이며, 크롬(Cr)과는 관계가 없다."],
