      choices: ["허파꽈리(폐포)","기관","기관지","세기관지","후두"],
      answerIndex: 0,
      explainCorrect: "가스교환은 허파꽈리(폐포)와 이를 둘러싼 모세혈관 사이에서 일어난다. 허파꽈리의 얇은 상피와 모세혈관 내피가 이루는 호흡막(respiratory membrane)을 통해 산소와 이산화탄소가 확산으로 교환된다.",
      explainWrong: ["","기관은 공기가 지나가는 통로로, 벽이 두꺼워 가스교환이 일어나지 않는다.","기관지는 기관에서 갈라진 공기 통로이며 가스교환 장소가 아니다.","세기관지는 허파꽈리(폐포)로 이어지는 가는 통로로, 종말세기관지(terminal bronchiole)까지는 가스교환에 참여하지 않는다.","후두는 발성과 기도 보호를 담당하는 상기도의 일부이다."],
