      choices: ["분압 차이에 따른 확산(diffusion)","ATP를 소모하는 능동수송(active transport)","운반체 단백질에 의한 촉진확산(facilitated diffusion)","세포막 함입에 의한 세포내섭취(endocytosis)","정수압 차이에 의한 여과(filtration)"],
      answerIndex: 0,
      explainCorrect: "산소는 분압이 높은 허파꽈리(폐포) 공기에서 분압이 낮은 모세혈관 혈액 쪽으로, 이산화탄소는 그 반대 방향으로 확산한다. 가스교환은 에너지나 운반체 없이 분압 기울기만으로 일어나는 단순확산(simple diffusion)이다.",
      explainWrong: ["","가스교환에는 ATP가 소모되지 않으며, 능동수송(active transport)은 이온이나 영양소 운반에 쓰인다.","산소와 이산화탄소는 지질막을 직접 통과하므로 운반체 단백질이 필요하지 않다.","세포내섭취(endocytosis)는 큰 입자나 액체를 막으로 싸서 들여오는 방식으로 가스 이동과 무관하다.","여과(filtration)는 사구체 여과처럼 압력 차이로 액체가 밀려 나가는 현상이며 가스교환의 원리가 아니다."],
