      choices: ["숨뇌(연수)의 호흡중추가 자극되어 호흡이 빨라지고 깊어진다","호흡중추가 억제되어 호흡수가 줄어든다","동맥혈 pH가 알칼리 쪽으로 이동한다","허파꽈리(폐포) 환기량이 줄어 이산화탄소가 더 쌓인다","말초 화학수용체가 억제되어 반응이 사라진다"],
