      explainWrong: ["","이산화탄소 증가는 호흡중추를 억제하는 것이 아니라 자극하여 환기를 늘린다.","이산화탄소가 늘면 탄산(H₂CO₃)이 증가하여 pH는 산성 쪽으로 이동한다.","정상 조절에서는 환기량이 늘어나 이산화탄소를 배출하는 방향으로 반응한다.","말초 화학수용체(목동맥토리 등)도 이산화탄소와 pH 변화에 의해 억제가 아니라 자극된다."],
