      answerIndex: 0,
      explainCorrect: "전자현미경(EM) 검사에서는 미세구조 보존이 우수한 2~2.5% 글루타르알데히드(glutaraldehyde)로 1차 고정하고, 사산화오스뮴(OsO₄)으로 후고정(post-fixation)한다. 글루타르알데히드는 침투가 느리므로 조직을 1 mm 내외의 작은 조각으로 잘라 고정한다.",
      explainWrong: ["","10% 중성완충포르말린(NBF)은 광학현미경(LM)용 일상 고정액으로, 미세구조 보존력은 글루타르알데히드(glutaraldehyde)보다 떨어진다.","95% 에탄올은 세포진(cytology) 도말 고정용으로, 수축이 심해 전자현미경(EM) 검사에 부적합하다.","부앵(Bouin)액은 피크르산(picric acid) 함유 고정액으로 미세구조가 손상되어 전자현미경(EM)에 쓰지 않는다.","아세톤은 일부 효소조직화학(enzyme histochemistry)에서 쓰는 고정·탈수제로, 전자현미경(EM)의 표준 고정액이 아니다."],
