      explainCorrect: "카르노이(Carnoy)액은 무수에탄올·클로로포름·빙초산(glacial acetic acid)의 혼합액으로 침투와 고정이 매우 빠르고, 수용성인 글리코겐(glycogen)을 비교적 잘 보존한다. 다만 수축이 심하고 지질이 용해되는 단점이 있다.",
      explainWrong: ["","젠커(Zenker)액은 수은 함유 고정액으로, 글리코겐(glycogen) 보존 목적의 알코올계 고정액이 아니다.","부앵(Bouin)액은 피크르산(picric acid) 함유 수용액으로, 수용성 글리코겐(glycogen) 보존에는 알코올계 고정액보다 불리하다.","10% 중성완충포르말린(NBF)은 수용액이어서 고정 중 글리코겐(glycogen)이 일부 용출될 수 있다.","헬리(Helly)액은 수은염과 중크롬산칼륨(K₂Cr₂O₇)에 포르말린을 더한 고정액으로 조혈조직 고정 등에 쓰인다."],
