      explainCorrect: "EDTA는 칼슘 이온과 착화합물을 형성하여 뼈에서 칼슘을 서서히 제거하는 킬레이트제(chelating agent)이다. 탈회(decalcification) 속도는 느리지만 핵산과 항원의 손상이 적어 면역조직화학(IHC)이나 분자검사가 필요한 검체에 유리하다.",
      explainWrong: ["","질산은 탈회(decalcification) 속도가 빠른 강산 탈회제로, 킬레이트 방식이 아니다.","염산도 수소 이온으로 칼슘염을 녹이는 산 탈회제(decalcifying agent)이다.","포름산(formic acid)은 탈회(decalcification) 속도와 조직 보존의 균형이 좋은 약산 탈회제이다.","트리클로로아세트산(TCA)은 산성 탈회제(decalcifying agent)로 킬레이트제(chelating agent)에 해당하지 않는다."],
