      choices: ["X선 촬영으로 잔존 석회화를 확인한다","탈회액(decalcifying solution)의 색 변화를 육안으로 관찰한다","조직의 무게 감소율을 측정한다","고정액의 pH 변화를 측정한다","조직 표면의 냄새 변화를 확인한다"],
