      choices: ["피부 검체는 표피와 진피가 한 절편에 함께 나오도록 세워서 포매(embedding)한다","관강 장기는 점막면이 절단면과 평행하게 눕혀서 포매(embedding)한다","조직을 몰드 중앙에 놓기만 하면 방향은 고려하지 않아도 된다","작은 생검일수록 방향을 고려할 필요가 없다","여러 조각은 서로 겹쳐 쌓아 한 덩어리로 포매(embedding)한다"],
