      explainCorrect: "포매(embedding) 방향은 진단에 필요한 면이 절편에 나오도록 결정한다. 피부는 표피에서 진피·피하까지의 층 구조가 한 절편에 보이도록 절단면에 수직으로 세워 포매하며, 관강 장기도 벽의 전층이 나오게 방향을 잡는다.",
      explainWrong: ["","관강 장기는 점막에서 장막까지 전층이 보이도록 벽을 절단면에 수직으로 포매(embedding)해야 한다.","방향이 틀리면 진단에 필요한 층 구조가 절편에 나오지 않아 재포매가 필요해진다.","작은 생검일수록 면삭(trimming) 중에 대상 부위가 소실되기 쉬워 방향 결정이 더욱 중요하다.","조각을 겹쳐 놓으면 각 조각의 절단면이 고르게 나오지 않아 판독이 어렵다."],
