      explainWrong: ["","산성 색소가 세포질 단백에 결합하는 것은 에오신(eosin)의 염색 원리이다.","지용성 색소의 용해는 오일레드 O(Oil red O) 같은 지방염색의 원리이다.","은 이온의 환원·침착은 세망섬유(reticular fiber) 염색 등 은염색(silver stain)의 원리이다.","효소 반응에 의한 발색은 면역조직화학(IHC)의 검출 원리이다."],
