      answerIndex: 0,
      explainCorrect: "에오신(eosin)은 음전하를 띠는 산성 색소로, 양전하를 띠는 세포질 단백·교원섬유(collagen fiber)·적혈구 등과 결합하여 분홍에서 적색까지의 색조로 염색한다. 성분에 따른 염색 강도 차이가 조직의 대비를 만든다.",
      explainWrong: ["","핵을 청색으로 염색하는 염기성 색소 역할은 헤마톡실린(hematoxylin)이 한다.","지방방울을 염색하는 지용성 색소는 오일레드 O(Oil red O)나 수단 계열이다.","에오신(eosin)은 핵산이 아니라 세포질 단백에 친화성을 갖는 색소이다.","에오신(eosin)은 일반 광학현미경(LM)으로 관찰하는 색소로, 형광 전용 색소가 아니다."],
