      choices: ["약알칼리성 용액으로 처리하여 핵을 적자색에서 청색으로 바꾼다","강산 용액으로 처리하여 세포질의 색을 제거한다","고농도 알코올로 처리하여 절편의 수분을 제거한다","자일렌(xylene)으로 처리하여 절편의 파라핀을 녹여낸다","산화제로 처리하여 색소를 탈색한다"],
      answerIndex: 0,
