      choices: ["굴절률이 유리와 비슷하고 시간이 지나도 변색되지 않아야 한다","물에 잘 녹아 세척이 쉬워야 한다","색이 진하여 조직과 대비를 이루어야 한다","굳지 않고 항상 액체 상태를 유지해야 한다","강한 산성을 띠어 세균 오염을 막아야 한다"],
