      answerIndex: 0,
      explainCorrect: "PAS 염색은 과요오드산(periodic acid)이 당의 인접 수산기를 알데히드로 산화시키고, 이 알데히드가 Schiff 시약과 반응하여 적자색을 나타내는 원리이다. 글리코겐(glycogen), 중성 점액(neutral mucin), 기저막(basement membrane), 진균 세포벽 등 당질이 풍부한 구조가 양성을 보인다.",
