      explainCorrect: "글리코겐(glycogen)은 디아스타제(아밀라제)에 의해 분해되므로, 효소 처리한 절편과 처리하지 않은 절편을 나란히 PAS 염색하여 비교한다. 효소 처리 후 양성이 소실되면 글리코겐이고, 그대로 남으면 중성 점액(neutral mucin) 등 다른 당질이다.",
