      answerIndex: 0,
      explainCorrect: "알시안블루(Alcian blue)는 양전하를 띠는 색소로, pH 2.5에서 카르복실기·황산기를 가진 산성 점액(acid mucin)과 결합하여 청색을 나타낸다. pH 1.0에서는 황산화 점액(sulfated mucin)만 선택적으로 염색되어 점액의 성상 감별에 이용된다.",
      explainWrong: ["","중성지방(triglyceride)은 동결절편(frozen section)에서 오일레드 O(Oil red O)로 증명한다.","글리코겐(glycogen)은 PAS 양성이지만 산성기가 없어 알시안블루(Alcian blue)에는 염색되지 않는다.","헤모시데린(hemosiderin)은 프러시안블루(Prussian blue) 반응으로 증명하는 철 색소이다.","아밀로이드(amyloid)는 콩고레드(Congo red) 염색과 편광 관찰로 증명한다."],
