      answerIndex: 0,
      explainCorrect: "GMS 염색은 크롬산(chromic acid)으로 진균 세포벽의 다당류를 알데히드로 산화시킨 뒤 메세나민 은용액(methenamine silver)의 은을 환원·침착시켜, 녹색 배경에 진균을 흑색으로 뚜렷하게 나타낸다. 칸디다(Candida), 아스페르길루스(Aspergillus), 폐포자충(Pneumocystis) 등의 증명에 널리 쓰인다.",
