      answerIndex: 0,
      explainCorrect: "수은 함유 고정액을 쓰면 조직에 흑갈색의 수은 색소(mercury pigment)가 침착한다. 탈파라핀(deparaffinization) 후 요오드 용액으로 수은을 요오드화수은으로 바꾸고, 남은 요오드의 갈색은 티오황산나트륨(하이포)으로 제거한다.",
      explainWrong: ["","알코올성 피크르산(picric acid)은 산성 포르말린에서 생긴 포르말린 색소(formalin pigment)를 제거하는 데 쓴다.","과망간산칼륨(KMnO₄)과 옥살산(oxalic acid)은 멜라닌(melanin) 표백에 쓰는 조합이다.","디아스타제(diastase)는 글리코겐(glycogen)을 분해하는 효소로 수은 색소(mercury pigment)와 무관하다.","염산 알코올과 암모니아수는 헤마톡실린(hematoxylin)의 분별(differentiation)과 블루잉(bluing)에 쓰는 시약이다."],
