      choices: ["무수 알코올","10% 중성완충포르말린(NBF)","부앵(Bouin)액","젠커(Zenker)액","EDTA 용액"],
      answerIndex: 0,
      explainCorrect: "요산염(urate) 결정은 물에 녹는 성질이 있어 수용성 고정액에 담그면 용출되어 사라진다. 통풍 결절(tophus)에서 결정을 관찰하려면 무수 알코올 같은 비수용성 고정액을 쓰고, 편광현미경(polarizing microscope)으로 음성 복굴절(negative birefringence)의 바늘 모양 결정을 확인한다.",
      explainWrong: ["","중성완충포르말린(NBF)은 수용액이어서 고정 중에 요산염(urate) 결정이 녹아 나간다.","부앵(Bouin)액도 수용성 고정액이며 산 성분까지 있어 결정 보존에 부적합하다.","젠커(Zenker)액은 수은염과 중크롬산칼륨(K₂Cr₂O₇)의 수용액으로 요산염(urate)이 용출된다.","EDTA는 탈회(decalcification)용 킬레이트제(chelating agent)로 고정액이 아니다."],
