      choices: ["칼날이 무디거나 블록이 따뜻함 - 칼날 교체와 블록 냉각","수조 온도가 낮음 - 수조 온도를 융점 이상으로 올림","고정 시간이 짧음 - 절편을 포르말린에 다시 담금","염색 시간이 짧음 - 헤마톡실린(hematoxylin) 염색을 반복함","봉입제(mounting medium)가 부족함 - 커버글라스를 다시 덮음"],
