      choices: ["OCT 컴파운드","파라핀","셀로이딘(celloidin)","에폭시 수지(epoxy resin)","캐나다 발삼(Canada balsam)"],
      answerIndex: 0,
      explainCorrect: "OCT(optimal cutting temperature) 컴파운드는 글리콜과 수지로 이루어진 수용성 포매제(embedding medium)로, 저온에서 조직과 함께 얼어 받침대에 고정하고 박절(sectioning)을 돕는다. 물에 녹으므로 염색 과정에서 쉽게 씻겨 나간다.",
      explainWrong: ["","파라핀은 탈수(dehydration)·투명(clearing)·침투(infiltration)를 거친 조직에 쓰는 포매제(embedding medium)로 동결절편(frozen section)에 쓰지 않는다.","셀로이딘(celloidin)은 대형·경조직용 포매제로 처리에 오랜 시간이 걸린다.","에폭시 수지(epoxy resin)는 전자현미경(EM)용 포매제이다.","캐나다 발삼(Canada balsam)은 천연수지 봉입제(mounting medium)로 포매제가 아니다."],
