      choices: ["고정하지 않은 조직을 동결하여 절편을 만든다","10% 중성완충포르말린(NBF)에 고정 후 파라핀 포매한다","2.5% 글루타르알데히드(glutaraldehyde)에 고정 후 에폭시 포매한다","부앵(Bouin)액에 고정 후 파라핀 포매한다","95% 에탄올에 고정 후 도말한다"],
