      explainWrong: ["","포르말린 고정·파라핀 포매(embedding) 조직은 광학현미경(LM) 검사용으로 쓰이며 면역형광(IF)에는 항원 손상이 크다.","글루타르알데히드(glutaraldehyde) 고정 조직은 전자현미경(EM) 검사용이다.","부앵(Bouin)액은 산성 고정액으로 면역글로불린(Ig) 항원성을 손상시킨다.","에탄올 도말은 세포진(cytology) 검사법으로 신장 생검의 면역형광(IF) 처리법이 아니다."],
