      explainWrong: ["","P파가 일정하게 선행하고 RR이 규칙적인 것은 정상 동리듬(NSR)의 소견이다.","PR간격이 점차 연장되다 QRS가 탈락하는 것은 2도 방실차단(AV block) I형(Wenckebach형)이다.","규칙적인 톱니 모양 F파는 심방조동(AFL)의 소견이다.","넓은 QRS의 규칙적 빈맥은 심실빈맥(VT)의 소견이다."],
