      choices: ["2도 방실차단(AV block) I형(Wenckebach형)","2도 방실차단(AV block) II형(Mobitz II형)","1도 방실차단(AV block)","3도 방실차단(AV block)","심방조동(AFL)"],
      answerIndex: 0,
      explainCorrect: "PR간격이 점진적으로 연장되다가 QRS군이 탈락하는 주기적 형태는 2도 방실차단(AV block) I형(Wenckebach 현상)의 전형적 소견이다. 방실결절(AV node) 수준의 차단으로 비교적 양성 경과를 보이는 경우가 많다.",
      explainWrong: ["","II형은 PR간격이 일정하게 유지되다가 예고 없이 QRS가 탈락하는 형태로, 예후가 더 나쁘다.","1도 방실차단(AV block)은 PR이 연장되어 있으나 QRS 탈락은 없다.","3도 방실차단은 P와 QRS가 완전히 독립적으로 나타난다.","심방조동(AFL)은 톱니 모양 F파가 특징인 심방 부정맥으로 PR의 점진적 연장과 무관하다."],
