      answerIndex: 0,
      explainCorrect: "심실조기수축(PVC)은 심실 내 이소성 병소에서 조기에 흥분이 시작되므로 선행 P파가 없고, 정상 전도로를 거치지 않아 QRS가 0.12초 이상으로 넓고 기괴하다. 완전 보상휴지기(compensatory pause)가 따르는 것이 전형적이며, 연속 3개 이상이면 심실빈맥(VT)으로 본다.",
      explainWrong: ["","심방조기수축(PAC)은 조기 P파가 선행하고 QRS 모양은 대개 정상(좁은 형태)이다.","방실접합부 조기수축(PJC)도 QRS는 좁으며, P파가 없거나 역행성으로 나타난다.","심방세동(AF)은 산발적 조기박동이 아니라 지속적으로 RR이 불규칙한 리듬이다.","동성부정맥(sinus arrhythmia)은 호흡에 따라 RR간격이 서서히 변하는 것으로 조기박동이 아니다."],
