      explainWrong: ["","심방세동(AF)은 심방파가 불규칙한 잔물결(f파)이고 RR간격도 완전히 불규칙하다.","심실빈맥(VT)은 넓은 QRS군 자체가 빠르게 이어지는 리듬으로 톱니파와 무관하다.","동성빈맥(sinus tachycardia)은 정상 P파가 100회/분 이상으로 빨라진 것일 뿐 톱니파가 없다.","이단맥(bigeminy)은 정상박동과 조기수축이 번갈아 나타나는 형태로 규칙적 F파가 없다."],
