      choices: ["호흡에 따른 흉곽 움직임과 전극 접촉 상태의 변화","60 Hz 교류전원의 간섭","골격근의 미세한 떨림","기록지 이동 속도의 오설정","감도(교정)의 오설정"],
      answerIndex: 0,
      explainCorrect: "기선동요(baseline wander)는 호흡에 따른 흉곽 움직임, 전극과 피부 사이 접촉저항의 변동, 땀이나 전극풀 마름 등이 원인이 되어 기선이 느리게 오르내리는 현상이다. 전극을 다시 부착하고 필요하면 잠시 호흡을 멈춘 상태에서 기록한다.",
      explainWrong: ["","교류 간섭은 60 Hz의 빠르고 규칙적인 잡음으로 나타나며 느린 기선 이동과 다르다.","근육 떨림은 불규칙한 가는 잔떨림으로 혼입되며 기선의 완만한 동요와 구별된다.","기록 속도 오설정은 파형의 시간 폭을 바꿀 뿐 기선을 움직이지 않는다.","감도 오설정은 파형의 진폭을 바꿀 뿐 기선동요(baseline wander)를 만들지 않는다."],
