      choices: ["적합한 곡선들 중 가장 큰 두 FVC 값의 차이가 150 mL 이내","한 번의 시도만으로 판정을 마친다","모든 시도의 FVC가 정확히 일치해야 한다","가장 큰 값과 작은 값의 차이가 1 L 이내면 된다","재현성은 결과 판정과 무관하다"],
