      choices: ["FEV1이 기저치보다 12% 이상 그리고 200 mL 이상 증가","FEV1이 기저치보다 5% 이상 증가","FVC가 50 mL 이상 증가","FEV1/FVC가 1% 이상 변화","잔기량(RV)이 12% 이상 증가"],
