      answerIndex: 0,
      explainCorrect: "최대환기량(MVV)은 피검자에게 12초(또는 15초)간 최대한 빠르고 깊게 호흡시키고, 그동안의 환기량을 60초 값으로 환산하여 L/min 단위로 보고한다. 1분 내내 시키면 과호흡으로 어지럼 등이 생길 수 있어 짧게 측정한 뒤 환산한다.",
      explainWrong: ["","안정 호흡 1분의 환기량은 분시환기량(minute ventilation)이지 최대환기량(MVV)이 아니다.","최대 흡기 후 한 번의 최대 호기는 폐활량(VC) 측정이다.","숨 참기 시간의 측정은 최대환기량과 전혀 다른 검사이다.","안정 시 환기량 기반 계산은 최대 노력 시의 환기 능력을 반영하지 못한다."],
