      explainWrong: ["","ST분절이 짧아지고 QT가 단축되는 것은 고칼슘혈증(hypercalcemia)의 소견이다.","좁고 뾰족한 T파는 고칼륨혈증(hyperkalemia)의 초기 소견이다.","PR 단축과 델타파(delta wave)는 WPW증후군의 조기흥분(pre-excitation) 소견으로 전해질 이상과 무관하다.","여러 유도의 ST분절 상승은 급성 심근 손상이나 심막염(pericarditis)을 시사한다."],
