      stem: "심전도(ECG)에서 PR간격이 일정하게 유지되다가 예고 없이 P파 뒤의 QRS군이 탈락한다. 이 부정맥과 임상적 의미로 옳은 것은?",
      choices: ["2도 방실차단(AV block) II형이며 완전 방실차단(AV block)으로 진행할 위험이 크다","2도 방실차단(AV block) I형이며 대부분 양성 경과를 보인다","1도 방실차단(AV block)이며 모든 P파가 심실로 전도된다","3도 방실차단(AV block)이며 P파와 QRS가 완전히 해리되어 있다","심방조기수축(PAC)이며 조기 P파 뒤 QRS가 정상으로 나온다"],
      answerIndex: 0,
