      explainWrong: ["","폭이 좁고 얕은 q파는 심실중격의 정상 탈분극(depolarization)으로 생기는 생리적 q파이다.","매우 작은 q파는 정상에서도 흔히 보이며 병적 의미가 없다.","V6의 작은 q파는 중격 탈분극에 의한 정상 소견이다.","aVR은 심장을 반대 방향에서 보는 유도라 정상에서도 깊은 Q파나 QS형이 나타난다."],
