      choices: ["일산화탄소헤모글로빈(HbCO)이 산소헤모글로빈(HbO₂)처럼 인식되어 실제보다 높게 표시된다","일산화탄소헤모글로빈(HbCO) 때문에 실제보다 항상 크게 낮게 표시된다","일산화탄소헤모글로빈(HbCO)은 빛을 흡수하지 않아 정확하게 표시된다","맥동 신호가 사라져 SpO₂가 0%로 표시된다","실제 포화도와 관계없이 85% 부근에 고정되어 표시된다"],
