      explainCorrect: "일산화탄소헤모글로빈(HbCO)은 적색광 흡광 특성이 산소헤모글로빈(HbO₂)과 비슷하여 일반 맥박산소측정기(pulse oximeter)가 이를 산소헤모글로빈으로 인식한다. 그 결과 실제 산소포화도가 낮아도 SpO₂는 정상처럼 높게 나오므로, 여러 파장을 쓰는 CO-oximetry로 동맥혈을 분석해 확인해야 한다.",
      explainWrong: ["","일산화탄소헤모글로빈(HbCO)은 오히려 산소헤모글로빈(HbO₂)으로 잘못 계산되므로 값이 낮아지지 않는다.","일산화탄소헤모글로빈도 빛을 흡수하며, 그 흡광 특성 때문에 측정 오차가 생긴다.","일산화탄소 중독 자체가 맥동 신호를 없애지는 않는다.","85% 부근으로 고정되는 현상은 메트헤모글로빈혈증(methemoglobinemia)에서 보이는 특징이다."],
