      choices: ["눈앞에서 여러 주파수의 섬광을 단계적으로 주어 광과민 반응을 확인한다","3~5분간 깊고 빠르게 호흡시켜 이상파의 출현을 유도한다","전날 밤 잠을 재우지 않고 다음날 기록하여 이상파를 유도한다","헤드폰으로 클릭음을 들려주어 뇌간의 청각 반응을 기록한다","바둑판 무늬를 반전시켜 시각 전도로의 잠복기를 측정한다"],
      answerIndex: 0,
