      choices: ["짧은 삽입전위(insertional activity) 뒤 전기적 침묵","지속적인 섬유자발전위(fibrillation potential)","반복되는 양성예파(positive sharp wave)","급강하 폭격음 같은 근긴장성 방전(myotonic discharge)","고진폭 다상성 운동단위전위(MUAP)의 연속 출현"],
