      choices: ["2~3 Hz 저빈도 자극에서 복합근활동전위(CMAP)의 진폭이 점차 감소한다","고빈도 자극 뒤 복합근활동전위(CMAP)의 진폭이 2배 이상 증가한다","자극 빈도와 관계없이 복합근활동전위(CMAP)의 진폭이 일정하다","첫 자극부터 복합근활동전위(CMAP)가 전혀 기록되지 않는다","자극을 반복할수록 복합근활동전위(CMAP)의 잠복기가 짧아진다"],
