      explainCorrect: "F파는 운동신경을 최대상(supramaximal) 강도로 자극했을 때 흥분이 역방향(antidromic)으로 척수 전각세포(anterior horn cell)까지 올라갔다가 일부 세포에서 되돌아 내려와 근육에서 기록되는 늦은 반응이다. 신경 근위부와 신경근을 지나므로 길랭-바레증후군(GBS) 초기처럼 근위부 병변을 평가하는 데 유용하며, 반응마다 잠복기와 모양이 조금씩 다르다.",
