      answerIndex: 0,
      explainCorrect: "초음파 장비는 깊이에 따른 감쇠(attenuation)를 일정하다고 가정하고 보상한다. 그런데 액체가 찬 낭종은 주변 조직보다 감쇠가 적어 그 뒤쪽에 초음파가 더 강하게 도달하므로 실제보다 밝게 표시되는데, 이를 후방에코증강(posterior acoustic enhancement)이라 하며 낭성 병변을 시사하는 소견이다.",
