      choices: ["노력성폐활량(FVC)만 감소하고 1초율(FEV1/FVC)은 정상 또는 증가","폐확산능(DLCO)만 단독으로 증가","총폐용량(TLC)이 현저히 증가하고 잔기량(RV)은 감소","최대호기유량(PEF)만 증가하고 FEV1은 정상","1초율(FEV1/FVC) 감소와 함께 FEV1 감소"],
