      explainCorrect: "ALP와 GGT는 모두 담세관막(canalicular membrane)에 존재하는 효소로 담즙 정체(cholestasis) 시 함께 상승한다. ALP는 뼈에서도 오르지만 GGT는 골질환에서 오르지 않으므로, 두 효소의 동반 상승은 담도 기원임을 뒷받침한다.",
      explainWrong: ["","CK와 알돌라아제(aldolase)는 골격근 손상에서 상승하는 조합이다.","AST와 CK-MB의 조합은 심근 손상 쪽을 시사한다.","아밀라아제(amylase)는 췌장·침샘, 트로포닌(troponin)은 심근 표지자로 담도 폐쇄의 조합이 아니다.","LD는 비특이적이고 산성 인산분해효소(ACP)는 전립선 관련 효소로 담도 지표가 아니다."],
