      explainCorrect: "리파아제(lipase)는 거의 췌장에서만 유래하여 특이성이 높고, 상승이 1~2주까지 지속되어 아밀라아제(3~5일 내 정상화)보다 진단 창이 넓다. 아밀라아제는 침샘 질환이나 신부전(renal failure) 등에서도 올라 특이성이 낮다.",
