      explainWrong: ["","소변 빌리루빈(bilirubin)이 음성인 것은 지용성 간접빌리루빈(indirect bilirubin)만 상승한 용혈성 황달(hemolytic jaundice)의 소견이다.","요당(glucosuria) 양성은 고혈당(hyperglycemia)이나 신성 당뇨(renal glycosuria)의 소견으로 황달과 직접 관련이 없다.","케톤뇨(ketonuria)는 케톤산증(ketoacidosis)이나 기아 상태의 소견이다.","아질산염(nitrite) 양성은 세균뇨(bacteriuria)를 시사하는 소견으로 황달과 무관하다."],
