      stem: "NAD(P)H의 생성이나 소모를 이용하는 효소법(UV법)에서 흡광도를 측정하는 파장은?",
      choices: ["340 nm","280 nm","405 nm","540 nm","620 nm"],
      answerIndex: 0,
      explainCorrect: "환원형 조효소(coenzyme) NADH와 NADPH는 340 nm에서 특징적인 흡수 극대를 보이며, 산화형(NAD+, NADP+)은 이 파장에서 흡수가 거의 없다. 이 차이를 이용해 AST, ALT, LD 등 탈수소효소(dehydrogenase) 연계 반응의 활성을 340 nm에서 측정한다.",
      explainWrong: ["","280 nm는 방향족 아미노산(aromatic amino acid)에 의한 단백질의 흡수 파장이다.","405 nm는 p-니트로페놀(p-nitrophenol) 발색을 이용하는 ALP 측정 등에 쓰이는 파장이다.","540 nm는 시안메트헤모글로빈(HiCN)법 등 가시부 발색 측정에 쓰이는 파장이다.","620 nm는 일부 색소 반응의 가시부 측정 파장으로 NADH 측정과 무관하다."],
