      explainWrong: ["","VLDL이 증가하면 혈장 전체가 균일하게 탁해질 뿐 상층 크림층을 만들지는 않는다.","LDL은 입자가 작아 혈장을 탁하게 만들지 않으며 냉장 방치로 층이 생기지 않는다.","HDL은 가장 작고 밀도가 높은 지단백(lipoprotein)으로 혈장 외관에 영향을 주지 않는다.","IDL은 VLDL에서 LDL로 가는 중간 대사산물로 크림층의 원인이 아니다."],
