      explainCorrect: "뷰렛(biuret) 반응은 알칼리 조건에서 Cu2+가 두 개 이상의 펩티드 결합(peptide bond)과 배위하여 자주색 착물을 형성하는 원리이다. 발색 정도는 펩티드 결합 수에 비례하므로 단백 종류에 관계없이 총단백을 정량할 수 있어 자동화 분석의 표준법으로 쓰인다.",
      explainWrong: ["","색소 결합에 의한 흡수 파장 이동은 BCG 등 알부민 측정법의 원리이다.","280 nm 자외부 흡수는 단백 정량에 이용될 수 있으나 뷰렛(biuret) 반응과는 다른 원리이다.","질소량 적정은 켈달(Kjeldahl)법으로 기준법 성격의 방법이며 뷰렛(biuret) 반응이 아니다.","산 침전 후 혼탁도(turbidity) 측정은 소변·뇌척수액(CSF)의 저농도 단백 측정에 쓰이는 방식이다."],
