      explainWrong: ["","CA19-9는 췌장암과 담도암의 대표 표지자이다.","CEA는 대장암 추적에 주로 쓰인다.","AFP는 간세포암(HCC)과 난황낭종양(yolk sac tumor)의 표지자로, 난소 상피암의 표지자가 아니다.","PSA는 전립선 특이 표지자이다."],
