      answerIndex: 0,
      explainCorrect: "헤파린은 안티트롬빈(AT)과 결합하여 트롬빈과 Xa인자 등의 불활성화 속도를 크게 높인다. 칼슘을 제거하지 않으므로 삼투취약성(osmotic fragility) 검사, 혈액가스 분석, 일부 생화학 검사에 쓰인다.",
      explainWrong: ["","칼슘 킬레이트는 EDTA의 작용기전이다.","칼슘과 불용성 염을 만들어 침전시키는 것은 옥살산염(oxalate)의 기전이다.","해당 효소(에놀레이스) 억제는 플루오르화나트륨(NaF)의 작용으로 혈당 보존 목적이다.","비타민K 의존 인자(II, VII, IX, X)의 합성 억제는 경구 항응고제 와파린(warfarin)의 기전이다."],
