      explainWrong: ["","헤마토크릿을 혈색소로 나누고 ×10한 값으로 분자와 분모가 뒤바뀌었다.","×100 대신 ×10을 곱한 값이다.","×1000을 곱한 값으로 단위 환산 오류이다.","혈색소와 헤마토크릿을 곱하고 10으로 나눈 값으로 공식이 틀렸다."],
