      choices: ["검체를 37℃로 가온한 후 재측정한다","검체를 냉장 보관한 후 재측정한다","시트르산 튜브로 재채혈하여 측정한다","희석 배수를 낮추어 재측정한다","헤파린 튜브로 재채혈하여 측정한다"],
