      explainWrong: ["","혈청철과 TIBC가 모두 감소하고 페리틴이 증가하는 것은 만성질환빈혈(ACD)의 소견이다.","혈청철과 페리틴 증가는 혈색소증(hemochromatosis)이나 철적모구빈혈(sideroblastic anemia) 같은 철 과부하 상태의 소견이다.","철 지표가 모두 정상인 소구성 빈혈은 지중해빈혈(thalassemia) 형질에서 흔하다.","철결핍에서는 트랜스페린 합성이 늘어 TIBC가 증가하므로 TIBC 감소는 맞지 않는다."],
