      choices: ["만성질환빈혈(ACD)","철결핍빈혈(IDA)","β-지중해빈혈 형질(β-thalassemia trait)","철적모구빈혈(sideroblastic anemia)","거대적아구성빈혈(megaloblastic anemia)"],
