      explainWrong: ["","철결핍빈혈(IDA)은 페리틴이 감소하고 TIBC가 증가하므로 이 결과와 반대이다.","지중해빈혈(thalassemia) 형질은 철 지표가 대체로 정상이며 MCV가 더 뚜렷하게 낮다.","철적모구빈혈(sideroblastic anemia)은 철 이용 장애로 혈청철이 증가하므로 혈청철 감소와 맞지 않는다.","거대적아구성빈혈(megaloblastic anemia)은 MCV가 증가하는 대구성 빈혈이다."],
