      answerIndex: 0,
      explainCorrect: "HbS는 β글로빈 유전자의 점돌연변이(point mutation)로 6번째 글루탐산이 소수성인 발린으로 바뀐 이상혈색소이다. 탈산소 상태에서 중합하여 적혈구를 낫 모양으로 변형시키고 혈관 폐색과 용혈을 일으킨다.",
      explainWrong: ["","β6 글루탐산이 라이신으로 바뀐 것은 HbC이다.","β26 글루탐산이 라이신으로 바뀐 것은 동남아시아에 흔한 HbE이다.","α사슬 유전자 결손은 α-지중해빈혈(α-thalassemia)의 원인이다.","γ사슬 4개로 이루어진 사량체는 Hb Bart's로 α-지중해빈혈(α-thalassemia) 태아에서 나타난다."],
