      choices: ["Howell-Jolly 소체","Heinz 소체","Pappenheimer 소체","Cabot 고리","호염기성 반점(basophilic stippling)"],
      answerIndex: 0,
      explainCorrect: "Howell-Jolly 소체는 탈핵 과정에서 남은 DNA 조각으로 Wright 염색에서 둥근 보라색 점으로 보인다. 정상적으로는 비장이 제거하므로 비장절제(splenectomy)나 기능적 무비증(functional asplenia)에서 증가하며, 거대적아구성빈혈(megaloblastic anemia)에서도 관찰된다.",
      explainWrong: ["","Heinz 소체는 변성 혈색소 침전물로 Wright 염색에서는 보이지 않고 초생체염색(supravital stain)으로 확인한다.","Pappenheimer 소체는 비헴철을 포함한 작은 과립으로 Prussian blue에 양성이다.","Cabot 고리는 적혈구 내 고리나 8자 모양의 가는 선으로 유사분열방추 잔여물로 여겨진다.","호염기성 반점(basophilic stippling)은 RNA 응집에 의한 다수의 미세 과립으로 납중독(lead poisoning)에서 뚜렷하다."],
