      choices: ["시안메트헤모글로빈(HiCN)법","산화헤모글로빈(HbO₂)법","알칼리헤마틴(alkaline hematin)법","Sahli법","SLS-헤모글로빈법"],
      answerIndex: 0,
      explainCorrect: "시안메트헤모글로빈(HiCN)법은 ICSH가 권장하는 혈색소 측정 표준법이다. 페리시안화칼륨(potassium ferricyanide)이 혈색소를 메트헤모글로빈(MetHb)으로 산화하고, 시안화 이온(CN⁻)이 결합하여 안정한 시안메트헤모글로빈을 만든 뒤 540 nm에서 흡광도를 측정한다.",
      explainWrong: ["","산화헤모글로빈(HbO₂)법은 희석 알칼리 용액에서 산화헤모글로빈의 흡광도를 측정하며 Drabkin 시약을 쓰지 않는다.","알칼리헤마틴(alkaline hematin)법은 수산화나트륨(NaOH)으로 혈색소를 알칼리 헤마틴으로 바꾸는 방법이다.","Sahli법은 염산(HCl)으로 산성 헤마틴(acid hematin)을 만들어 육안 비색하는 오래된 방법이다.","SLS-헤모글로빈법은 시안화물 대신 라우릴황산나트륨(sodium lauryl sulfate)을 쓰는 자동분석기 방법이다."],
