      choices: ["설프헤모글로빈(SHb)","산화헤모글로빈(HbO₂)","메트헤모글로빈(MetHb)","카르복시헤모글로빈(HbCO)","탈산소헤모글로빈(HHb)"],
      answerIndex: 0,
      explainCorrect: "시안메트헤모글로빈(HiCN)법은 대부분의 혈색소 유도체를 시안메트헤모글로빈으로 전환하여 함께 측정한다. 그러나 설프헤모글로빈(SHb)은 시안메트헤모글로빈으로 전환되지 않아 측정되지 않는다. 설프헤모글로빈은 일부 약물 노출 시 생기며 정상에서는 거의 존재하지 않는다.",
      explainWrong: ["","산화헤모글로빈(HbO₂)은 페리시안화물(ferricyanide)에 의해 메트헤모글로빈(MetHb)으로 산화된 뒤 측정된다.","메트헤모글로빈(MetHb)은 시안화 이온(CN⁻)과 바로 결합하여 시안메트헤모글로빈(HiCN)이 된다.","카르복시헤모글로빈(HbCO)은 전환이 느리지만 시간이 지나면 시안메트헤모글로빈(HiCN)으로 전환되어 측정된다.","탈산소헤모글로빈(HHb)도 산화 과정을 거쳐 시안메트헤모글로빈(HiCN)으로 측정된다."],
