      explainWrong: ["","버피코트(buffy coat) 1 mm를 적혈구층에 포함하여 19 ÷ 45로 계산한 값이다.","혈장층과 버피코트 길이(27 mm)를 전체로 나눈 값으로 적혈구가 아닌 층의 비율이다.","적혈구층을 적혈구 이외 부분의 길이(27 mm)로 나눈 값으로 분모가 틀렸다.","적혈구층 길이를 그대로 백분율로 읽은 값이다."],
