      explainWrong: ["","1 µL는 깊이 0.1 mm를 반영하지 않은 값이다.","0.01 µL는 깊이를 0.01 mm로 잘못 적용한 값이다.","0.004 µL는 중앙 대구획 안의 소구획(0.2 mm × 0.2 mm) 1개의 부피이다.","0.04 µL는 면적 0.4 mm²에 깊이를 곱한 값으로 대구획 1개의 부피가 아니다."],
