      answerIndex: 0,
      explainCorrect: "고칼슘혈증, 신기능 저하, 빈혈, 골병변에 연전형성(rouleaux)까지 더해지면 다발골수종(MM)을 의심한다. 한 클론의 형질세포가 동일한 면역글로불린(M단백)을 대량 생산하므로 전기영동에서 주로 γ 영역에 좁고 뾰족한 띠가 나타나며, 면역고정전기영동(IFE)으로 종류를 확인한다.",
      explainWrong: ["","넓고 완만한 γ 영역 증가는 다클론성 고감마글로불린혈증(polyclonal hypergammaglobulinemia)으로 만성 염증이나 간질환에서 보인다.","β-γ 가교(β-γ bridging)는 IgA 증가를 동반한 간경변(liver cirrhosis)의 특징적 소견이다.","α1 띠 소실은 α1-안티트립신(AAT) 결핍증을 시사한다.","골수종에서 알부민은 정상이거나 감소하며 증가하지 않는다."],
