      explainCorrect: "Sudan black B는 과립 막의 인지질 등 지질에 결합하는 지용성 색소로, 호중구 계열에서 MPO와 거의 같은 양성 양상을 보인다. 효소 활성에 의존하지 않아 보관 기간이 긴 도말에서도 염색이 유지된다.",
      explainWrong: ["","PAS는 글리코겐 등 다당류를 염색하며 림프모구와 적백혈병(erythroleukemia) 적아구에서 양성을 보인다.","비특이적 에스테라아제(NSE)는 단구계를 확인하는 효소 염색이다.","Prussian blue 염색은 골수의 저장철과 환상철적모구(ring sideroblast)를 확인한다.","주석산 저항 산성인산분해효소(TRAP) 염색은 털세포백혈병(HCL) 진단에 쓰인다."],
