      explainWrong: ["","급성전골수구백혈병(APL)은 MPO와 Sudan black B 강양성이 특징이다.","급성단구성백혈병(acute monocytic leukemia)은 NaF로 억제되는 비특이적 에스테라아제(NSE) 양성이 특징이다.","만성골수백혈병(CML)은 성숙 과립구 증가 질환으로 NAP 점수 감소가 주된 세포화학 소견이다.","진성적혈구증가증(PV)은 PAS 괴상 양성 모세포가 나타나는 질환이 아니다."],
