      stem: "항원 자극을 받은 T세포가 분비하여 T세포 자신과 주변 T세포의 증식을 촉진하는 대표적인 사이토카인(cytokine)은?",
      choices: ["IL-2","IL-1","IL-4","IL-6","IL-10"],
      answerIndex: 0,
      explainCorrect: "IL-2는 활성화된 T세포가 분비하는 T세포 성장인자로, 자가분비(autocrine)와 주변분비(paracrine) 방식으로 T세포 클론의 증식을 이끈다. 사이클로스포린(cyclosporine) 같은 면역억제제는 IL-2 생산을 억제하여 이식 거부반응을 막는다.",
      explainWrong: ["","IL-1은 주로 대식세포(macrophage)가 분비하는 염증성 사이토카인으로 발열을 일으키는 내인성 발열원(endogenous pyrogen)이다.","IL-4는 Th2 세포가 분비하며 B세포의 IgE 클래스 전환(class switching)을 유도한다.","IL-6는 간에서 CRP 등 급성기 반응물질(acute phase reactant) 생성을 자극하는 대표적인 사이토카인이다.","IL-10은 대식세포(macrophage)와 T세포의 활성을 억제하는 항염증성 사이토카인이다."],
