      choices: ["Rh 부적합에 의한 신생아용혈성질환(HDFN)","꽃가루에 의한 알레르기 비염(allergic rhinitis)","이종 항혈청 투여 후 혈청병(serum sickness)","옻나무에 의한 접촉피부염(contact dermatitis)","아르투스(Arthus) 반응"],
      answerIndex: 0,
      explainCorrect: "II형(세포독성) 과민반응(hypersensitivity)은 항체가 세포나 조직에 고정된 항원에 직접 결합해 보체(complement) 활성화, 옵소닌 식작용, 항체의존세포독성(ADCC)으로 세포를 손상시킨다. 모체 항-D IgG가 태아 Rh 양성 적혈구를 파괴하는 신생아용혈성질환(HDFN), 용혈성 수혈반응(HTR), 자가면역용혈빈혈(AIHA)이 대표적이다.",
      explainWrong: ["","꽃가루 알레르기 비염(allergic rhinitis)은 IgE와 비만세포(mast cell)가 매개하는 I형 반응이다.","혈청병(serum sickness)은 이종 단백에 대한 면역복합체(immune complex)가 전신에 침착되는 III형 반응이다.","옻나무 접촉피부염(contact dermatitis)은 감작 T세포가 매개하는 IV형 반응이다.","아르투스 반응(Arthus reaction)은 주사 부위에 면역복합체(immune complex)가 국소적으로 침착되는 III형 반응이다."],
