      stem: "가용성 항원과 항체가 만든 면역복합체(immune complex)가 혈관벽이나 사구체에 침착되어 조직 손상을 일으키는 과민반응(hypersensitivity)의 예는?",
      choices: ["혈청병(serum sickness)","기관지 천식(bronchial asthma)","자가면역용혈빈혈(AIHA)","중증근무력증(myasthenia gravis)","이식편대숙주병(GVHD)"],
      answerIndex: 0,
      explainCorrect: "III형 과민반응(hypersensitivity)은 항원이 약간 과잉인 상태에서 생긴 중간 크기의 면역복합체(immune complex)가 제거되지 않고 혈관벽, 사구체, 관절에 침착된 뒤 보체(complement)를 활성화하고 호중구(neutrophil)를 끌어들여 손상을 일으킨다. 혈청병(serum sickness), 아르투스 반응(Arthus reaction), SLE의 루푸스신염(lupus nephritis), 사슬알균 감염 후 사구체신염(PSGN)이 대표적이다.",
      explainWrong: ["","기관지 천식(bronchial asthma)은 IgE와 비만세포(mast cell)가 매개하는 I형 반응이다.","자가면역용혈빈혈(AIHA)은 적혈구 표면 항원에 대한 자가항체로 생기는 II형 반응이다.","중증근무력증(myasthenia gravis)은 아세틸콜린 수용체(AChR)에 대한 자가항체가 신호 전달을 막는 II형 반응이다.","이식편대숙주병(GVHD)은 공여자 T세포가 수혜자 조직을 공격하는 T세포 매개 반응으로 IV형에 해당한다."],
