      explainWrong: ["","weak D는 에피토프(epitope)가 대부분 정상이고 항원 수가 적은 것으로 대개 항D를 만들지 않는다.","D−−는 C·c·E·e 항원이 결손된 것으로 D 항원은 오히려 강하게 발현된다.","Rh null은 모든 Rh 항원이 없어 D양성으로 판정되지 않는다.","DEL은 흡착·해리 검사(adsorption-elution)로만 확인되는 극미량 D 발현형으로 일상 검사에서 D음성으로 판정된다."],
