      explainWrong: ["","성분채집혈소판(SDP)에도 소량의 적혈구와 혈장이 섞일 수 있어 ABO·Rh 확인이 필요하다.","성분채집혈소판(SDP)도 20~24°C에서 진탕 보관하며 냉장 보관하지 않는다.","제제에 살아 있는 림프구가 있으므로 수혈 관련 이식편대숙주병(TA-GVHD) 예방에는 방사선조사(irradiation)가 필요하다.","HLA와 혈소판 특이항원은 그대로 남아 있어 동종면역(alloimmunization)에 의한 불응증(refractoriness)이 생길 수 있다."],
