      answerIndex: 0,
      explainCorrect: "방사선조사(irradiation)는 혈액제제에 섞인 공혈자 T림프구의 증식 능력을 없애 수혈 관련 이식편대숙주병(TA-GVHD)을 예방한다. 조혈모세포이식(HSCT) 환자, 선천성 면역결핍 환자, 혈연 공혈자의 혈액, HLA 적합 혈소판 수혈에서 필요하다. 백혈구여과제거(leukoreduction)만으로는 확실하게 예방되지 않는다.",
      explainWrong: ["","발열성 비용혈성 수혈반응(FNHTR)은 백혈구여과제거(leukoreduction)로 줄인다.","혈액제제에 쓰는 조사 선량으로는 세균이 멸균되지 않는다.","IgA 결핍 환자의 아나필락시스(anaphylaxis)는 세척 제제로 혈장 단백을 제거해 예방한다.","방사선조사(irradiation)는 백혈구의 HLA 항원을 없애지 않으므로 동종면역(alloimmunization) 예방에는 백혈구제거(leukoreduction)가 필요하다."],
