      choices: ["즉시 수혈을 중단하고 생리식염수로 정맥로를 유지한다","해열제를 투여하고 수혈 속도를 늦춘다","항히스타민제를 투여한 뒤 수혈을 계속한다","남은 혈액백을 폐기하고 새 혈액으로 교체한다","이뇨제를 투여하면서 같은 혈액을 계속 수혈한다"],
      answerIndex: 0,
      explainCorrect: "급성 용혈성 수혈반응(AHTR)이 의심되므로 즉시 수혈을 중단하고 생리식염수로 정맥로를 확보한 뒤 의사와 혈액은행에 보고한다. 혈액백과 수혈세트, 수혈 후 새로 채혈한 검체를 혈액은행으로 보내 환자·혈액 확인, ABO 재검사, DAT, 혈장 유리혈색소(free Hb) 등을 확인한다. 대부분 환자 확인 오류에 의한 ABO 부적합이 원인이다.",
      explainWrong: ["","해열제와 속도 조절은 경미한 발열 반응에 대한 대응으로 용혈 소견이 있을 때는 부적절하다.","항히스타민제는 경미한 두드러기 반응에 쓰며 용혈이 의심되면 수혈을 계속하면 안 된다.","혈액백은 원인 조사를 위해 혈액은행으로 반납해야 하며 폐기하면 안 된다.","용혈이 의심되는 혈액을 계속 넣으면 용혈과 신손상이 악화된다."],
