      explainWrong: ["","Staphylococcus epidermidis는 novobiocin 감수성이며 카테터(catheter)·인공삽입물 관련 감염을 잘 일으킨다.","Staphylococcus haemolyticus는 novobiocin 감수성 응고효소 음성 포도알균(CoNS)이다.","Staphylococcus lugdunensis는 novobiocin 감수성이며 PYR 양성, 결합형 응고효소(clumping factor) 양성으로 황색포도알균(Staphylococcus aureus)과 혼동될 수 있다.","Staphylococcus aureus는 응고효소(coagulase) 양성이므로 조건에 맞지 않는다."],
