      explainWrong: ["","Streptococcus pyogenes는 CAMP 음성, 마뇨산 가수분해(hippurate hydrolysis) 음성이며 바시트라신(bacitracin) 감수성이다.","Enterococcus faecalis는 담즙에스쿨린(bile esculin) 양성, 6.5% NaCl 발육으로 감별한다.","Streptococcus pneumoniae는 옵토킨(optochin) 감수성, 담즙용해(bile solubility) 양성인 α용혈 쌍알균이다.","Streptococcus gallolyticus(S. bovis)는 담즙에스쿨린(bile esculin) 양성인 D군 사슬알균으로 대장암과의 관련이 알려져 있다."],
