      explainWrong: ["","Haemophilus parainfluenzae는 V 인자만 요구하며 X 인자는 필요 없다.","Haemophilus ducreyi는 X 인자만 요구하는 연성하감(chancroid)의 원인균이다.","Bordetella pertussis는 X·V 인자를 요구하지 않으며 Bordet-Gengou 배지에서 배양한다.","Neisseria meningitidis는 그람음성 쌍알균으로 혈액한천에서 단독으로 발육한다."],
