      explainWrong: ["","Neisseria gonorrhoeae는 포도당(glucose)만 분해하고 맥아당(maltose)은 분해하지 않는다.","Neisseria lactamica는 포도당·맥아당과 함께 유당(lactose)도 분해하며 ONPG 양성이다.","Moraxella catarrhalis는 어떤 당도 분해하지 않으며 DNase 양성, 부티르산 에스테라제(butyrate esterase) 양성이다.","Neisseria sicca는 포도당·맥아당 외에 자당(sucrose)도 분해하는 상기도 정상균총(normal flora)이다."],
