      stem: "화상 창상에서 분리된 그람음성간균의 성상이 다음과 같다. 이 균은?\n· TSI: K/K, H2S 음성\n· 옥시다아제(oxidase) 양성, 운동성 양성\n· 배지를 청록색으로 물들이는 수용성 색소\n· 포도(옥수수 토르티야) 냄새, 42℃에서 발육",
