      explainWrong: ["","Acinetobacter baumannii는 비발효균(nonfermenter)이지만 옥시다아제(oxidase) 음성, 비운동성인 구간균(coccobacillus)이며 색소를 만들지 않는다. 다제내성(MDR) 병원감염균으로 중요하다.","Stenotrophomonas maltophilia는 옥시다아제(oxidase) 음성이고 카바페넴(carbapenem)에 내재 내성인 비발효균이다.","Burkholderia cepacia는 옥시다아제(oxidase)가 약양성이고 노란 색소를 만들 수 있으며 청록색 색소나 포도 냄새가 없다.","Escherichia coli는 발효균으로 TSI A/A를 보이며 옥시다아제(oxidase) 음성이다."],
