      stem: "영유아의 겨울철 급성 위장관염(gastroenteritis)의 주요 원인으로, 이중 캡시드(capsid) 구조와 11개 분절의 이중가닥 RNA 유전체를 가진 바이러스는?",
      choices: ["로타바이러스(rotavirus)","노로바이러스(norovirus)","장관 아데노바이러스(40·41형)","아스트로바이러스(astrovirus)","엔테로바이러스(enterovirus)"],
      answerIndex: 0,
      explainCorrect: "로타바이러스(rotavirus)는 레오바이러스과(Reoviridae)에 속하며 11개 분절 dsRNA를 가진 외피(envelope) 없는 바이러스로 5세 미만 영유아 설사의 대표적 원인이다. 대변 검체에서 항원 검사(EIA, 면역크로마토그래피)나 RT-PCR로 진단하며 경구 생백신(live vaccine)이 있다.",
      explainWrong: ["","노로바이러스(norovirus)는 단일가닥 RNA 칼리시바이러스(Calicivirus)로 전 연령의 집단 식중독과 겨울철 구토·설사를 일으킨다.","장관 아데노바이러스(enteric adenovirus)는 이중가닥 DNA 바이러스로 분절 유전체가 없다.","아스트로바이러스(astrovirus)는 별 모양의 단일가닥 RNA 바이러스로 비교적 경한 설사를 일으킨다.","엔테로바이러스(enterovirus)는 단일가닥 RNA 피코르나바이러스(Picornavirus)로 장에서 증식하지만 주로 수족구병(HFMD)·무균성 뇌수막염(aseptic meningitis)을 일으킨다."],
