      answerIndex: 0,
      explainCorrect: "왼쪽 균은 둥근 구균이며 크리스탈바이올렛(crystal violet)의 진한 보라색을 그대로 유지하고 있다. 두꺼운 펩티도글리칸(peptidoglycan) 세포벽 때문에 알코올 탈색 후에도 색이 빠지지 않은 것이므로 그람양성 구균(GPC)으로 판독한다. 여러 개가 무리 지은 배열은 포도상구균(Staphylococcus)을 먼저 떠올리게 한다.",
      explainWrong: ["","그람음성 구균(GNC)은 탈색 후 사프라닌(safranin)에 대비염색(counterstain)되어 분홍~적색으로 보이며 흔히 강낭콩 모양의 쌍구균(diplococci)으로 관찰된다. 그림의 균은 진한 보라색이다.","그람양성 간균(GPR)은 보라색이지만 막대 모양이어야 한다. 그림의 균은 길이와 폭이 같은 둥근 형태이다.","그람음성 간균(GNR)은 분홍색 막대 모양으로 보인다. 색과 형태가 모두 그림과 다르다.","항산성 간균(AFB)은 항산 염색(acid-fast stain)에서 청색 배경 위의 적색 막대로 확인하며 그람 염색에서는 잘 염색되지 않는다. 그림은 보라색 구균이다."],
