      image: "images/prac-gram-neg-rods.svg",
      major: "microbiology",
      choices: ["그람음성 간균(GNR)","그람양성 간균(GPR)","그람음성 구균(GNC)","그람양성 구균(GPC)","항산성 간균(AFB)"],
      answerIndex: 0,
      explainCorrect: "왼쪽 균은 길쭉한 막대 모양이고 분홍~적색으로 염색되어 있다. 얇은 펩티도글리칸(peptidoglycan)층과 외막(outer membrane)을 가진 세균은 알코올 탈색 때 크리스탈바이올렛(crystal violet)이 빠지고 사프라닌(safranin)으로 대비염색(counterstain)되므로 그람음성 간균(GNR)으로 판독한다. 오른쪽의 보라색 구균과 색이 뚜렷하게 대비된다.",
      explainWrong: ["","그람양성 간균(GPR)은 탈색에 저항해 보라색 막대로 보인다. 그림 왼쪽 균은 적색이다.","그람음성 구균(GNC)은 같은 적색이지만 둥근 쌍구균(diplococci) 형태이다. 그림 왼쪽 균은 길쭉한 막대 모양이다.","그람양성 구균(GPC)은 보라색의 둥근 균이다. 오른쪽에 함께 그려진 균이 이 형태이며 문항이 묻는 왼쪽 균과는 다르다.","항산성 간균(AFB)은 Ziehl-Neelsen 등 항산 염색에서 적색으로 남는 균이며 그람 염색 소견으로 판정하지 않는다."],
