      answerIndex: 0,
      explainCorrect: "에오신(eosin)은 음전하를 띤 산성 염료로, 양전하를 띤 세포질 단백과 교원섬유(collagen fiber) 같은 세포외 기질(ECM)에 결합해 분홍색을 낸다. 범례의 분홍 칸은 이런 호산성(eosinophilic) 구조를 나타낸다.",
      explainWrong: ["","핵은 헤마톡실린(hematoxylin)에 물들어 청자색으로 보인다. 범례의 청자색 칸에 해당한다.","칼슘 침착물은 H&E에서 짙은 청자색 과립 덩어리로 보이며 von Kossa 염색에서 흑색이 된다.","세균 집락은 핵산이 많아 헤마톡실린(hematoxylin)에 물들어 청자색 덩어리로 보인다.","헤모시데린(hemosiderin)은 H&E에서 황금빛 갈색 과립으로 보이며 Prussian blue 염색에서 청색이 된다."],
